struct BeamSection {
  width: f64;
  height: f64;
  length: f64;
  elasticModulus: f64;
  yieldStrength: f64;
}

function secondMomentOfArea(sec: BeamSection): f64 {
  return (sec.width * sec.height * sec.height * sec.height) / 12.0;
}

function maxBendingStress(sec: BeamSection, tipLoad: f64): f64 {
  let moment: f64 = tipLoad * sec.length;
  let inertia: f64 = secondMomentOfArea(sec);
  let halfHeight: f64 = sec.height * 0.5;
  return (moment * halfHeight) / inertia;
}

function tipDeflection(sec: BeamSection, tipLoad: f64): f64 {
  let inertia: f64 = secondMomentOfArea(sec);
  return (tipLoad * sec.length * sec.length * sec.length) / (3.0 * sec.elasticModulus * inertia);
}

function safetyFactor(sec: BeamSection, tipLoad: f64): f64 {
  let sigmaMax: f64 = maxBendingStress(sec, tipLoad);
  return sec.yieldStrength / sigmaMax;
}

struct MotorParams {
  resistance: f64;
  inductance: f64;
  kt: f64;
  ke: f64;
  inertia: f64;
  damping: f64;
  vMax: f64;
}

function clampVoltage(v: f64, limit: f64): f64 {
  if (v > limit) {
    return limit;
  }
  if (v < -limit) {
    return -limit;
  }
  return v;
}

function simulateServoSpeed(p: MotorParams, targetOmega: f64, kp: f64, ki: f64, dt: f64, steps: i32): f64 {
  let omega: f64 = 0.0;
  let current: f64 = 0.0;
  let integralErr: f64 = 0.0;
  let k: i32 = 0;

  while (k < steps) {
    let err: f64 = targetOmega - omega;
    integralErr = integralErr + err * dt;
    let vCmd: f64 = clampVoltage(kp * err + ki * integralErr, p.vMax);
    let diDt: f64 = (vCmd - p.resistance * current - p.ke * omega) / p.inductance;
    let dOmegaDt: f64 = (p.kt * current - p.damping * omega) / p.inertia;
    current = current + diDt * dt;
    omega = omega + dOmegaDt * dt;
    k = k + 1;
  }
  return omega;
}

struct PumpSpec {
  shutoffHead: f64;
  headCoeff: f64;
  ratedSpeedRpm: f64;
  fluidDensity: f64;
  gravity: f64;
  peakEfficiency: f64;
  bepFlow: f64;
}

function pumpHead(spec: PumpSpec, flow: f64, speedRpm: f64): f64 {
  let ratio: f64 = speedRpm / spec.ratedSpeedRpm;
  let qScaled: f64 = flow / ratio;
  let hBase: f64 = spec.shutoffHead - spec.headCoeff * qScaled * qScaled;
  if (hBase < 0.0) {
    return 0.0;
  }
  return hBase * ratio * ratio;
}

function pumpEfficiency(spec: PumpSpec, flow: f64, speedRpm: f64): f64 {
  let ratio: f64 = speedRpm / spec.ratedSpeedRpm;
  let qBep: f64 = spec.bepFlow * ratio;
  let delta: f64 = (flow - qBep) / qBep;
  let eta: f64 = spec.peakEfficiency * (1.0 - 0.65 * delta * delta);
  if (eta < 0.1) {
    return 0.1;
  }
  return eta;
}

function shaftPowerWatts(spec: PumpSpec, flow: f64, speedRpm: f64): f64 {
  let head: f64 = pumpHead(spec, flow, speedRpm);
  let eta: f64 = pumpEfficiency(spec, flow, speedRpm);
  let hydraulicPower: f64 = spec.fluidDensity * spec.gravity * flow * head;
  return hydraulicPower / eta;
}

function sweepMaxHydraulicPower(spec: PumpSpec, speedRpm: f64, samples: i32): f64 {
  let bestPower: f64 = 0.0;
  let i: i32 = 1;
  while (i <= samples) {
    let q: f64 = 0.002 * i;
    let h: f64 = pumpHead(spec, q, speedRpm);
    let pHyd: f64 = spec.fluidDensity * spec.gravity * q * h;
    if (pHyd > bestPower) {
      bestPower = pHyd;
    }
    i = i + 1;
  }
  return bestPower;
}

struct PackConfig {
  capacityAh: f64;
  internalResistance: f64;
  thermalCapJK: f64;
  coolingConductanceWK: f64;
  ambientTempC: f64;
  maxTempC: f64;
  derateTempC: f64;
}

function selectBmsMode(soc: f64, tempC: f64, reqCurrentA: f64, cfg: PackConfig): i32 {
  if (tempC >= cfg.maxTempC) {
    return 4;
  }
  if (soc <= 0.05 && reqCurrentA > 0.0) {
    return 0;
  }
  if (soc >= 0.98 && reqCurrentA < 0.0) {
    return 0;
  }
  if (tempC >= cfg.derateTempC) {
    return 3;
  }
  if (reqCurrentA > 0.0) {
    return 2;
  }
  if (reqCurrentA < 0.0) {
    return 1;
  }
  return 0;
}

function effectiveCurrent(mode: i32, reqCurrentA: f64): f64 {
  if (mode == 4 || mode == 0) {
    return 0.0;
  }
  if (mode == 3) {
    return reqCurrentA * 0.5;
  }
  return reqCurrentA;
}

function simulateBmsCycle(cfg: PackConfig, initSoc: f64, reqCurrentA: f64, dt: f64, steps: i32): f64 {
  let soc: f64 = initSoc;
  let tempC: f64 = cfg.ambientTempC;
  let k: i32 = 0;

  while (k < steps) {
    let mode: i32 = selectBmsMode(soc, tempC, reqCurrentA, cfg);
    let current: f64 = effectiveCurrent(mode, reqCurrentA);
    let qGen: f64 = current * current * cfg.internalResistance;
    let qCool: f64 = cfg.coolingConductanceWK * (tempC - cfg.ambientTempC);
    tempC = tempC + ((qGen - qCool) / cfg.thermalCapJK) * dt;
    soc = soc - (current * dt) / (cfg.capacityAh * 3600.0);
    k = k + 1;
  }
  return tempC;
}

import { QuadParams, AltitudeGains } from "./types.msx";
import { verticalAcceleration } from "./propulsion.msx";
import { computeRotorRpmCommand } from "./controller.msx";

function runAltitudeHoldMission(p: QuadParams, g: AltitudeGains, targetZ: f64, dt: f64, steps: i32): f64 {
  let z: f64 = 0.0;
  let vz: f64 = 0.0;
  let step: i32 = 0;

  while (step < steps) {
    let rpmCmd: f64 = computeRotorRpmCommand(p, g, targetZ, z, vz);
    let az: f64 = verticalAcceleration(p, rpmCmd, vz);
    vz = vz + az * dt;
    z = z + vz * dt;
    if (z < 0.0) {
      z = 0.0;
      vz = 0.0;
    }
    step = step + 1;
  }
  return z;
}

